//! Scenarios for `claude canary compare`, driven through the real `xtask`
//! binary at the component boundary (the same way `affected_ci.rs` runs it).
//!
//! The captures are hand-written from the evidence in the expected table
//! (`source` fields cite #2084 and #2101); they are not generated by running
//! the tool. The checked-in table is exercised by
//! `checked_in_table_is_exercised`.
//!
//! - A: the hand-written capture matches the expected table: every row is
//!   VERIFIED except `login_screen` whose expected value is `null`, so the
//!   exit code is 3 (UNVERIFIED), never 0.
//! - B: one `final_record` differs in the expected copy: the row reports
//!   MISMATCH with `-`/`+` lines naming `kind=permission` and
//!   `kind=question`, and the exit code is 1.
//! - C: the capture omits a scenario: it is named MISSING and the code is 1.
//! - D: the capture stores a `msg` field, or a `msg=<b64>` record segment:
//!   compare refuses it with exit 2.
//! - E: the capture row lacks `attention`: the row reports MISMATCH with a
//!   `-`-only leaf line and the code is 1.

// Rust guideline compliant 2026-11-13

use std::path::PathBuf;
use std::process::Output;

use pohunek_test_support::env::TestEnv;

fn fixture(name: &str) -> PathBuf {
    pohunek_test_support::manifest_dir()
        .join("tests/fixtures/claude_canary")
        .join(name)
}

struct Canary {
    env: TestEnv,
}

impl Canary {
    fn new() -> Self {
        let env = TestEnv::new().expect("hermetic test environment");
        // A hermetic environment with the checkout marker `xtask` requires.
        let marker = env.cwd().join("crates/xtask/Cargo.toml");
        std::fs::create_dir_all(marker.parent().expect("parent")).expect("mkdir");
        std::fs::write(marker, "").expect("marker");
        Self { env }
    }

    fn compare(&self, expected: &str, capture: &str) -> Output {
        self.compare_at(expected, capture)
    }

    fn compare_at(&self, expected: &str, capture: &str) -> Output {
        self.env
            .command(pohunek_test_support::bin_exe("xtask"))
            .current_dir(self.env.cwd())
            .args([
                "claude",
                "canary",
                "compare",
                "--expected",
                fixture(expected).to_str().expect("utf-8 path"),
                "--capture",
                fixture(capture).to_str().expect("utf-8 path"),
            ])
            .output()
            .expect("run xtask")
    }

    /// Runs `compare` against the checked-in expected table
    /// `compat/claude/canary/expected.json` of the repository.
    fn compare_checked_in(&self, capture: &str) -> Output {
        let expected =
            pohunek_test_support::manifest_dir().join("../../compat/claude/canary/expected.json");
        self.env
            .command(pohunek_test_support::bin_exe("xtask"))
            .current_dir(self.env.cwd())
            .args([
                "claude",
                "canary",
                "compare",
                "--expected",
                expected.to_str().expect("utf-8 path"),
                "--capture",
                fixture(capture).to_str().expect("utf-8 path"),
            ])
            .output()
            .expect("run xtask")
    }
}

fn stdout_of(output: &Output) -> String {
    String::from_utf8_lossy(&output.stdout).into_owned()
}

fn stderr_of(output: &Output) -> String {
    String::from_utf8_lossy(&output.stderr).into_owned()
}

#[test]
fn matching_capture_is_unverified_not_verified() {
    let canary = Canary::new();
    let output = canary.compare("expected.json", "capture-match.json");
    assert_eq!(
        output.status.code(),
        Some(3),
        "the login row is UNVERIFIED so the exit code is 3: stderr {}",
        stderr_of(&output)
    );
    assert!(
        stderr_of(&output).is_empty(),
        "a typed outcome exits without an error line: {}",
        stderr_of(&output)
    );
    let stdout = stdout_of(&output);
    assert!(
        stdout.contains("claude_version: Claude Code 2.1.323"),
        "the report prints the capture version: {stdout}"
    );
    assert!(
        stdout.contains("login_screen | null |"),
        "the login row shows a null expectation: {stdout}"
    );
    for (row, values) in [
        ("idle_after_turn", "state=done []"),
        (
            "permission_prompt",
            "state=blocked:kind=permission [approval_required]",
        ),
        (
            "mcp_elicitation",
            "state=blocked:kind=question [agent_blocked]",
        ),
        ("running_turn", "state=working []"),
    ] {
        assert!(
            stdout.contains(&format!("{row} | {values} | {values} | VERIFIED")),
            "the row {row} shows the fixture values: {stdout}"
        );
    }
    assert!(
        stdout.contains("login_screen | null | state=working [] | UNVERIFIED"),
        "the login row is UNVERIFIED: {stdout}"
    );
}

#[test]
fn differing_record_is_mismatch_with_diff_lines() {
    let canary = Canary::new();
    let output = canary.compare("expected-mismatch.json", "capture-match.json");
    assert_eq!(
        output.status.code(),
        Some(1),
        "a mismatch exits 1: stderr {}",
        stderr_of(&output)
    );
    let stdout = stdout_of(&output);
    assert!(
        stdout.contains(
            "permission_prompt | state=blocked:kind=question [approval_required] | state=blocked:kind=permission [approval_required] | MISMATCH"
        ),
        "the row shows the expected and observed values: {stdout}"
    );
    assert!(
        stdout.lines().any(
            |line| line.starts_with("- permission_prompt/final_record: ")
                && line.contains("kind=question")
        ),
        "a diff line names kind=question on the expected side: {stdout}"
    );
    assert!(
        stdout.lines().any(
            |line| line.starts_with("+ permission_prompt/final_record: ")
                && line.contains("kind=permission")
        ),
        "a diff line names kind=permission on the observed side: {stdout}"
    );
}

#[test]
fn missing_scenario_is_missing() {
    let canary = Canary::new();
    let output = canary.compare("expected.json", "capture-missing.json");
    assert_eq!(
        output.status.code(),
        Some(1),
        "a missing scenario exits 1: stderr {}",
        stderr_of(&output)
    );
    let stdout = stdout_of(&output);
    assert!(
        stdout.contains(
            "mcp_elicitation | state=blocked:kind=question [agent_blocked] | - | MISSING"
        ),
        "mcp_elicitation is named MISSING with the expected values: {stdout}"
    );
    assert!(
        stdout
            .lines()
            .any(|line| line.starts_with("- mcp_elicitation: ")
                && line.contains("present in expected, absent in capture")),
        "a key present on only one side prints only its `-` line: {stdout}"
    );
}

#[test]
fn capture_with_a_message_is_refused() {
    let canary = Canary::new();
    let output = canary.compare("expected.json", "capture-with-msg.json");
    assert_eq!(
        output.status.code(),
        Some(2),
        "a capture with a `msg` is a usage error: stderr {}",
        stderr_of(&output)
    );
    let diagnostic = format!("{}{}", stdout_of(&output), stderr_of(&output));
    assert!(
        diagnostic.contains("`msg`"),
        "the refusal names the stored message field: {diagnostic}"
    );
}

#[test]
fn capture_with_a_message_tail_is_refused() {
    let canary = Canary::new();
    let output = canary.compare("expected.json", "capture-with-msg-tail.json");
    assert_eq!(
        output.status.code(),
        Some(2),
        "a capture with a `msg=<b64>` record segment is a usage error: stderr {}",
        stderr_of(&output)
    );
    let diagnostic = format!("{}{}", stdout_of(&output), stderr_of(&output));
    assert!(
        diagnostic.contains("`msg`"),
        "the refusal names the message segment: {diagnostic}"
    );
}

#[test]
fn capture_row_without_attention_is_mismatch_with_one_sided_leaf() {
    let canary = Canary::new();
    let output = canary.compare("expected.json", "capture-missing-attention.json");
    assert_eq!(
        output.status.code(),
        Some(1),
        "a missing attention leaf exits 1: stderr {}",
        stderr_of(&output)
    );
    let stdout = stdout_of(&output);
    let minus: Vec<&str> = stdout
        .lines()
        .filter(|line| line.starts_with("- permission_prompt/attention: "))
        .collect();
    assert_eq!(
        minus.len(),
        1,
        "exactly one `-` line names the one-sided leaf: {stdout}"
    );
    assert!(
        !stdout
            .lines()
            .any(|line| line.starts_with("+ permission_prompt/attention: ")),
        "no `+` line exists for a missing leaf: {stdout}"
    );
}

#[test]
fn checked_in_table_is_exercised() {
    let canary = Canary::new();
    let output = canary.compare_checked_in("capture-match.json");
    assert_eq!(
        output.status.code(),
        Some(3),
        "the checked-in table matches the fixture with the login row UNVERIFIED: stderr {}",
        stderr_of(&output)
    );
}
